-- POS PostgreSQL baseline schema
-- Migration: 001_initial_schema.sql
-- Target: PostgreSQL 15+
-- UUIDs are generated by application; gen_random_uuid() defaults are convenience only.
-- Run in development first. This migration is not yet production-certified.

BEGIN;
CREATE SCHEMA IF NOT EXISTS pos;
SET search_path TO pos, public;

CREATE TABLE org_stores (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  code varchar(20) NOT NULL UNIQUE,
  name varchar(160) NOT NULL,
  timezone varchar(64) NOT NULL DEFAULT 'Asia/Jakarta',
  currency_code char(3) NOT NULL DEFAULT 'IDR',
  is_active boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE iam_users (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  employee_code varchar(40) NOT NULL UNIQUE,
  full_name varchar(160) NOT NULL,
  pin_hash text NOT NULL,
  status varchar(20) NOT NULL DEFAULT 'active' CHECK (status IN ('active','locked','inactive')),
  failed_pin_attempts smallint NOT NULL DEFAULT 0 CHECK (failed_pin_attempts BETWEEN 0 AND 5),
  locked_until timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE org_terminals (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  store_id uuid NOT NULL REFERENCES org_stores(id),
  code varchar(30) NOT NULL,
  name varchar(100),
  primary_cashier_id uuid REFERENCES iam_users(id),
  app_version varchar(40),
  is_active boolean NOT NULL DEFAULT true,
  disabled_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (store_id, code)
);

CREATE TABLE org_store_servers (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  store_id uuid NOT NULL REFERENCES org_stores(id),
  server_code varchar(40) NOT NULL UNIQUE,
  app_version varchar(40),
  status varchar(20) NOT NULL DEFAULT 'unknown',
  last_seen_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE org_terminal_status (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  terminal_id uuid NOT NULL REFERENCES org_terminals(id),
  status varchar(20) NOT NULL,
  observed_at timestamptz NOT NULL DEFAULT now(),
  app_version varchar(40),
  details jsonb
);
CREATE INDEX ix_terminal_status_terminal_time ON org_terminal_status(terminal_id, observed_at DESC);

CREATE TABLE iam_roles (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  code varchar(30) NOT NULL UNIQUE,
  name varchar(80) NOT NULL
);
CREATE TABLE iam_permissions (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  code varchar(100) NOT NULL UNIQUE,
  description text
);
CREATE TABLE iam_role_permissions (
  role_id uuid NOT NULL REFERENCES iam_roles(id) ON DELETE CASCADE,
  permission_id uuid NOT NULL REFERENCES iam_permissions(id) ON DELETE CASCADE,
  PRIMARY KEY (role_id, permission_id)
);
CREATE TABLE iam_user_store_assignments (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id uuid NOT NULL REFERENCES iam_users(id),
  store_id uuid NOT NULL REFERENCES org_stores(id),
  valid_from timestamptz NOT NULL DEFAULT now(),
  valid_until timestamptz,
  CHECK (valid_until IS NULL OR valid_until > valid_from)
);
CREATE INDEX ix_user_store_active ON iam_user_store_assignments(user_id, store_id, valid_until);
CREATE TABLE iam_user_role_assignments (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id uuid NOT NULL REFERENCES iam_users(id),
  role_id uuid NOT NULL REFERENCES iam_roles(id),
  store_id uuid REFERENCES org_stores(id),
  valid_from timestamptz NOT NULL DEFAULT now(),
  valid_until timestamptz,
  CHECK (valid_until IS NULL OR valid_until > valid_from)
);
CREATE INDEX ix_user_role_scope ON iam_user_role_assignments(user_id, store_id, valid_until);
CREATE TABLE iam_pin_reset_events (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id uuid NOT NULL REFERENCES iam_users(id),
  reset_by uuid NOT NULL REFERENCES iam_users(id),
  method varchar(30) NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE iam_terminal_authorizations (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id uuid NOT NULL REFERENCES iam_users(id),
  terminal_id uuid NOT NULL REFERENCES org_terminals(id),
  authorized_by uuid NOT NULL REFERENCES iam_users(id),
  expires_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE md_categories (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  code varchar(40) NOT NULL UNIQUE,
  name varchar(120) NOT NULL,
  parent_id uuid REFERENCES md_categories(id),
  sort_order integer NOT NULL DEFAULT 0,
  is_active boolean NOT NULL DEFAULT true,
  version bigint NOT NULL DEFAULT 1,
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE md_products (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  sku varchar(50) NOT NULL UNIQUE,
  name varchar(200) NOT NULL,
  description text,
  category_id uuid REFERENCES md_categories(id),
  base_uom_code varchar(20) NOT NULL,
  image_uri text,
  is_active boolean NOT NULL DEFAULT true,
  version bigint NOT NULL DEFAULT 1,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX ix_products_category_active ON md_products(category_id, is_active);
CREATE TABLE md_product_barcodes (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  product_id uuid NOT NULL REFERENCES md_products(id),
  barcode varchar(100) NOT NULL,
  barcode_type varchar(20) NOT NULL DEFAULT 'CODE128',
  is_active boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX uq_active_product_barcode ON md_product_barcodes(barcode) WHERE is_active;
CREATE INDEX ix_product_barcodes_product ON md_product_barcodes(product_id);
CREATE TABLE md_product_prices (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  product_id uuid NOT NULL REFERENCES md_products(id),
  price numeric(18,2) NOT NULL CHECK (price >= 0),
  valid_from timestamptz NOT NULL,
  valid_until timestamptz,
  version bigint NOT NULL,
  created_by uuid REFERENCES iam_users(id),
  created_at timestamptz NOT NULL DEFAULT now(),
  CHECK (valid_until IS NULL OR valid_until > valid_from),
  UNIQUE (product_id, version)
);
CREATE INDEX ix_product_prices_effective ON md_product_prices(product_id, valid_from, valid_until);
CREATE TABLE md_product_tax_rules (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  product_id uuid NOT NULL REFERENCES md_products(id),
  tax_code varchar(30) NOT NULL,
  tax_rate numeric(7,4) NOT NULL CHECK (tax_rate >= 0 AND tax_rate <= 100),
  valid_from timestamptz NOT NULL,
  valid_until timestamptz,
  version bigint NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  CHECK (valid_until IS NULL OR valid_until > valid_from),
  UNIQUE (product_id, tax_code, version)
);
CREATE INDEX ix_product_tax_effective ON md_product_tax_rules(product_id, valid_from, valid_until);
CREATE TABLE md_product_store_availability (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  product_id uuid NOT NULL REFERENCES md_products(id),
  store_id uuid NOT NULL REFERENCES org_stores(id),
  is_available boolean NOT NULL DEFAULT true,
  reason text,
  updated_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (product_id, store_id)
);
CREATE TABLE md_product_display_order (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  terminal_id uuid NOT NULL REFERENCES org_terminals(id),
  product_id uuid NOT NULL REFERENCES md_products(id),
  sort_order integer NOT NULL DEFAULT 0,
  is_favorite boolean NOT NULL DEFAULT false,
  UNIQUE (terminal_id, product_id)
);
CREATE TABLE md_uoms (
  code varchar(20) PRIMARY KEY,
  name varchar(80) NOT NULL,
  description text
);

CREATE TABLE md_customers (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  name varchar(160) NOT NULL,
  normalized_phone varchar(30) NOT NULL UNIQUE,
  address text,
  date_of_birth date,
  status varchar(20) NOT NULL DEFAULT 'active' CHECK (status IN ('active','inactive')),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE md_customer_merge_events (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  source_customer_id uuid NOT NULL REFERENCES md_customers(id),
  target_customer_id uuid NOT NULL REFERENCES md_customers(id),
  merged_by uuid NOT NULL REFERENCES iam_users(id),
  reason text NOT NULL,
  merged_at timestamptz NOT NULL DEFAULT now(),
  CHECK (source_customer_id <> target_customer_id)
);
CREATE TABLE md_customer_phone_aliases (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  customer_id uuid NOT NULL REFERENCES md_customers(id),
  normalized_phone varchar(30) NOT NULL UNIQUE,
  is_primary boolean NOT NULL DEFAULT false
);

CREATE TABLE md_promotions (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  code varchar(40) NOT NULL UNIQUE,
  name varchar(160) NOT NULL,
  promotion_type varchar(30) NOT NULL,
  starts_at timestamptz NOT NULL,
  ends_at timestamptz NOT NULL,
  priority integer NOT NULL DEFAULT 0,
  is_active boolean NOT NULL DEFAULT true,
  version bigint NOT NULL DEFAULT 1,
  CHECK (ends_at > starts_at)
);
CREATE TABLE md_promotion_conditions (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  promotion_id uuid NOT NULL REFERENCES md_promotions(id) ON DELETE CASCADE,
  condition_type varchar(30) NOT NULL,
  condition_data jsonb NOT NULL DEFAULT '{}'::jsonb
);
CREATE TABLE md_promotion_benefits (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  promotion_id uuid NOT NULL REFERENCES md_promotions(id) ON DELETE CASCADE,
  benefit_type varchar(30) NOT NULL,
  benefit_data jsonb NOT NULL DEFAULT '{}'::jsonb
);
CREATE TABLE md_promotion_products (
  promotion_id uuid NOT NULL REFERENCES md_promotions(id) ON DELETE CASCADE,
  product_id uuid NOT NULL REFERENCES md_products(id),
  scope_type varchar(20) NOT NULL DEFAULT 'include' CHECK (scope_type IN ('include','exclude')),
  PRIMARY KEY (promotion_id, product_id, scope_type)
);
CREATE TABLE md_promotion_quotas (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  promotion_id uuid NOT NULL REFERENCES md_promotions(id),
  total_limit bigint CHECK (total_limit IS NULL OR total_limit >= 0),
  per_customer_limit bigint CHECK (per_customer_limit IS NULL OR per_customer_limit >= 0),
  UNIQUE (promotion_id)
);
CREATE TABLE md_payment_methods (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  code varchar(30) NOT NULL UNIQUE,
  name varchar(80) NOT NULL,
  method_type varchar(30) NOT NULL,
  requires_reference boolean NOT NULL DEFAULT false,
  is_cash boolean NOT NULL DEFAULT false,
  is_active boolean NOT NULL DEFAULT true,
  version bigint NOT NULL DEFAULT 1
);

CREATE TABLE pos_carts (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  store_id uuid NOT NULL REFERENCES org_stores(id),
  terminal_id uuid NOT NULL REFERENCES org_terminals(id),
  created_by uuid NOT NULL REFERENCES iam_users(id),
  customer_id uuid REFERENCES md_customers(id),
  status varchar(20) NOT NULL DEFAULT 'open' CHECK (status IN ('open','held','converted','cancelled')),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX ix_carts_owner_status ON pos_carts(created_by, status);
CREATE TABLE pos_cart_lines (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  cart_id uuid NOT NULL REFERENCES pos_carts(id) ON DELETE CASCADE,
  product_id uuid NOT NULL REFERENCES md_products(id),
  sku_snapshot varchar(50) NOT NULL,
  name_snapshot varchar(200) NOT NULL,
  barcode_snapshot varchar(100),
  quantity integer NOT NULL CHECK (quantity > 0),
  unit_price_snapshot numeric(18,2) NOT NULL CHECK (unit_price_snapshot >= 0),
  note text,
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX ix_cart_lines_cart ON pos_cart_lines(cart_id);
CREATE TABLE pos_hold_orders (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  cart_id uuid NOT NULL UNIQUE REFERENCES pos_carts(id),
  hold_number varchar(50) NOT NULL,
  held_by uuid NOT NULL REFERENCES iam_users(id),
  held_at timestamptz NOT NULL DEFAULT now(),
  last_resumed_at timestamptz,
  status varchar(20) NOT NULL DEFAULT 'held' CHECK (status IN ('held','resumed','deleted'))
);
CREATE TABLE pos_cart_events (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  cart_id uuid NOT NULL REFERENCES pos_carts(id),
  event_type varchar(40) NOT NULL,
  actor_id uuid NOT NULL REFERENCES iam_users(id),
  occurred_at timestamptz NOT NULL DEFAULT now(),
  event_data jsonb
);

CREATE TABLE pos_sales (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  receipt_number varchar(80) NOT NULL UNIQUE,
  store_id uuid NOT NULL REFERENCES org_stores(id),
  terminal_id uuid NOT NULL REFERENCES org_terminals(id),
  cashier_id uuid NOT NULL REFERENCES iam_users(id),
  customer_id uuid REFERENCES md_customers(id),
  business_date date NOT NULL,
  status varchar(20) NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','payment_pending','paid','cancelled')),
  currency_code char(3) NOT NULL DEFAULT 'IDR',
  subtotal numeric(18,2) NOT NULL DEFAULT 0 CHECK (subtotal >= 0),
  discount_total numeric(18,2) NOT NULL DEFAULT 0 CHECK (discount_total >= 0),
  tax_total numeric(18,2) NOT NULL DEFAULT 0 CHECK (tax_total >= 0),
  rounding_amount numeric(18,2) NOT NULL DEFAULT 0,
  grand_total numeric(18,2) NOT NULL DEFAULT 0 CHECK (grand_total >= 0),
  created_at timestamptz NOT NULL DEFAULT now(),
  paid_at timestamptz,
  CHECK (status <> 'paid' OR paid_at IS NOT NULL)
);
CREATE INDEX ix_sales_store_date ON pos_sales(store_id, business_date, created_at);
CREATE INDEX ix_sales_cashier_time ON pos_sales(cashier_id, created_at DESC);
CREATE INDEX ix_sales_terminal_time ON pos_sales(terminal_id, created_at DESC);
CREATE TABLE pos_sale_lines (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  sale_id uuid NOT NULL REFERENCES pos_sales(id),
  product_id uuid REFERENCES md_products(id),
  sku_snapshot varchar(50) NOT NULL,
  name_snapshot varchar(200) NOT NULL,
  barcode_snapshot varchar(100),
  quantity integer NOT NULL CHECK (quantity > 0),
  unit_price numeric(18,2) NOT NULL CHECK (unit_price >= 0),
  gross_amount numeric(18,2) NOT NULL CHECK (gross_amount >= 0),
  discount_amount numeric(18,2) NOT NULL DEFAULT 0 CHECK (discount_amount >= 0),
  taxable_base numeric(18,2) NOT NULL CHECK (taxable_base >= 0),
  tax_code_snapshot varchar(30),
  tax_rate_snapshot numeric(7,4) NOT NULL DEFAULT 0 CHECK (tax_rate_snapshot >= 0 AND tax_rate_snapshot <= 100),
  tax_amount numeric(18,2) NOT NULL DEFAULT 0 CHECK (tax_amount >= 0),
  line_total numeric(18,2) NOT NULL CHECK (line_total >= 0),
  price_version bigint,
  tax_version bigint,
  promotion_snapshot jsonb
);
CREATE INDEX ix_sale_lines_product_sale ON pos_sale_lines(product_id, sale_id);
CREATE TABLE pos_sale_status_events (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  sale_id uuid NOT NULL REFERENCES pos_sales(id),
  old_status varchar(20),
  new_status varchar(20) NOT NULL,
  actor_id uuid REFERENCES iam_users(id),
  reason text,
  occurred_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE pos_sale_number_sequences (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  terminal_id uuid NOT NULL REFERENCES org_terminals(id),
  business_date date NOT NULL,
  next_number bigint NOT NULL CHECK (next_number > 0),
  updated_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (terminal_id, business_date)
);
CREATE TABLE pos_sale_discounts (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  sale_id uuid NOT NULL REFERENCES pos_sales(id),
  sale_line_id uuid REFERENCES pos_sale_lines(id),
  discount_type varchar(30) NOT NULL,
  amount numeric(18,2) NOT NULL CHECK (amount >= 0),
  source varchar(20) NOT NULL CHECK (source IN ('promotion','manual')),
  applied_by uuid REFERENCES iam_users(id),
  reason text,
  promotion_id uuid REFERENCES md_promotions(id)
);
CREATE TABLE pos_promotion_cancellations (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  sale_id uuid NOT NULL REFERENCES pos_sales(id),
  promotion_id uuid NOT NULL REFERENCES md_promotions(id),
  reason text NOT NULL,
  cancelled_by uuid NOT NULL REFERENCES iam_users(id),
  cancelled_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE md_promotion_usage (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  promotion_id uuid NOT NULL REFERENCES md_promotions(id),
  customer_id uuid REFERENCES md_customers(id),
  sale_id uuid NOT NULL REFERENCES pos_sales(id),
  usage_key varchar(120) NOT NULL UNIQUE,
  used_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE md_manual_discount_limits (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  role_id uuid REFERENCES iam_roles(id),
  supervisor_user_id uuid REFERENCES iam_users(id),
  max_percent numeric(7,4) NOT NULL DEFAULT 0 CHECK (max_percent >= 0 AND max_percent <= 100),
  max_amount numeric(18,2) NOT NULL DEFAULT 0 CHECK (max_amount >= 0),
  valid_from timestamptz NOT NULL DEFAULT now(),
  valid_until timestamptz,
  CHECK (role_id IS NOT NULL OR supervisor_user_id IS NOT NULL),
  CHECK (valid_until IS NULL OR valid_until > valid_from)
);

CREATE TABLE pos_payments (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  sale_id uuid NOT NULL REFERENCES pos_sales(id),
  payment_method_id uuid NOT NULL REFERENCES md_payment_methods(id),
  amount numeric(18,2) NOT NULL CHECK (amount > 0),
  status varchar(24) NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','confirmed','failed','payment_pending')),
  reference_number varchar(120),
  confirmed_by uuid REFERENCES iam_users(id),
  confirmed_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  CHECK (status <> 'confirmed' OR confirmed_at IS NOT NULL)
);
CREATE INDEX ix_payments_sale ON pos_payments(sale_id);
CREATE INDEX ix_payments_method_time ON pos_payments(payment_method_id, created_at DESC);
CREATE TABLE pos_payment_evidence (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  payment_id uuid NOT NULL REFERENCES pos_payments(id),
  file_uri text NOT NULL,
  content_type varchar(100),
  checksum varchar(128),
  uploaded_by uuid REFERENCES iam_users(id),
  uploaded_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE pos_payment_events (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  payment_id uuid NOT NULL REFERENCES pos_payments(id),
  old_status varchar(24),
  new_status varchar(24) NOT NULL,
  actor_id uuid REFERENCES iam_users(id),
  reason text,
  occurred_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE pos_refunds (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  original_sale_id uuid NOT NULL REFERENCES pos_sales(id),
  store_id uuid NOT NULL REFERENCES org_stores(id),
  terminal_id uuid NOT NULL REFERENCES org_terminals(id),
  processed_by uuid NOT NULL REFERENCES iam_users(id),
  refund_method_id uuid NOT NULL REFERENCES md_payment_methods(id),
  reason text NOT NULL,
  total_amount numeric(18,2) NOT NULL CHECK (total_amount > 0),
  status varchar(20) NOT NULL DEFAULT 'approved' CHECK (status IN ('draft','approved','paid','cancelled')),
  created_at timestamptz NOT NULL DEFAULT now(),
  completed_at timestamptz
);
CREATE INDEX ix_refunds_original_sale ON pos_refunds(original_sale_id);
CREATE TABLE pos_refund_lines (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  refund_id uuid NOT NULL REFERENCES pos_refunds(id),
  original_sale_line_id uuid NOT NULL REFERENCES pos_sale_lines(id),
  quantity integer NOT NULL CHECK (quantity > 0),
  refund_amount numeric(18,2) NOT NULL CHECK (refund_amount > 0),
  item_received boolean NOT NULL DEFAULT false,
  item_resalable boolean NOT NULL DEFAULT false,
  stock_return_eligible boolean GENERATED ALWAYS AS (item_received AND item_resalable) STORED
);
CREATE INDEX ix_refund_lines_original ON pos_refund_lines(original_sale_line_id);
CREATE TABLE pos_refund_payments (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  refund_id uuid NOT NULL REFERENCES pos_refunds(id),
  payment_method_id uuid NOT NULL REFERENCES md_payment_methods(id),
  amount numeric(18,2) NOT NULL CHECK (amount > 0),
  reference_number varchar(120),
  status varchar(20) NOT NULL DEFAULT 'pending'
);
CREATE TABLE pos_refund_events (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  refund_id uuid NOT NULL REFERENCES pos_refunds(id),
  event_type varchar(40) NOT NULL,
  actor_id uuid NOT NULL REFERENCES iam_users(id),
  reason text,
  occurred_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE cash_drawers (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  store_id uuid NOT NULL REFERENCES org_stores(id),
  terminal_id uuid NOT NULL UNIQUE REFERENCES org_terminals(id),
  fixed_float_amount numeric(18,2) NOT NULL CHECK (fixed_float_amount >= 0),
  currency_code char(3) NOT NULL DEFAULT 'IDR',
  is_active boolean NOT NULL DEFAULT true
);
CREATE TABLE cash_drawer_float_history (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  drawer_id uuid NOT NULL REFERENCES cash_drawers(id),
  old_amount numeric(18,2) NOT NULL,
  new_amount numeric(18,2) NOT NULL CHECK (new_amount >= 0),
  changed_by uuid NOT NULL REFERENCES iam_users(id),
  reason text NOT NULL,
  changed_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE cash_sessions (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  drawer_id uuid NOT NULL REFERENCES cash_drawers(id),
  store_id uuid NOT NULL REFERENCES org_stores(id),
  terminal_id uuid NOT NULL REFERENCES org_terminals(id),
  cashier_id uuid NOT NULL REFERENCES iam_users(id),
  status varchar(20) NOT NULL DEFAULT 'open' CHECK (status IN ('open','closed')),
  opening_counted numeric(18,2) NOT NULL CHECK (opening_counted >= 0),
  closing_counted numeric(18,2),
  expected_cash numeric(18,2),
  variance_amount numeric(18,2),
  opened_at timestamptz NOT NULL DEFAULT now(),
  closed_at timestamptz,
  CHECK (closing_counted IS NULL OR closing_counted >= 0),
  CHECK ((status = 'open' AND closed_at IS NULL) OR (status = 'closed' AND closed_at IS NOT NULL))
);
CREATE UNIQUE INDEX uq_one_open_session_per_cashier ON cash_sessions(cashier_id) WHERE status = 'open';
CREATE UNIQUE INDEX uq_one_open_session_per_drawer ON cash_sessions(drawer_id) WHERE status = 'open';
CREATE TABLE cash_ledger_entries (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  drawer_id uuid NOT NULL REFERENCES cash_drawers(id),
  session_id uuid REFERENCES cash_sessions(id),
  entry_type varchar(30) NOT NULL,
  direction varchar(3) NOT NULL CHECK (direction IN ('in','out')),
  amount numeric(18,2) NOT NULL CHECK (amount > 0),
  source_type varchar(40),
  source_id uuid,
  idempotency_key varchar(140) UNIQUE,
  actor_id uuid NOT NULL REFERENCES iam_users(id),
  approved_by uuid REFERENCES iam_users(id),
  reason text,
  occurred_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX ix_cash_ledger_drawer_time ON cash_ledger_entries(drawer_id, occurred_at);
CREATE TABLE cash_handover_events (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  drawer_id uuid NOT NULL REFERENCES cash_drawers(id),
  from_session_id uuid NOT NULL REFERENCES cash_sessions(id),
  to_session_id uuid NOT NULL REFERENCES cash_sessions(id),
  from_cashier_id uuid NOT NULL REFERENCES iam_users(id),
  to_cashier_id uuid NOT NULL REFERENCES iam_users(id),
  amount numeric(18,2) NOT NULL CHECK (amount >= 0),
  variance numeric(18,2) NOT NULL DEFAULT 0,
  supervisor_id uuid REFERENCES iam_users(id),
  reason text,
  confirmed_at timestamptz NOT NULL DEFAULT now(),
  CHECK (from_session_id <> to_session_id)
);
CREATE TABLE cash_deposits (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  drawer_id uuid NOT NULL REFERENCES cash_drawers(id),
  store_id uuid NOT NULL REFERENCES org_stores(id),
  amount numeric(18,2) NOT NULL CHECK (amount >= 0),
  expected_amount numeric(18,2) NOT NULL CHECK (expected_amount >= 0),
  variance numeric(18,2) NOT NULL,
  recorded_by uuid NOT NULL REFERENCES iam_users(id),
  reason text NOT NULL,
  deposited_at timestamptz NOT NULL DEFAULT now(),
  status varchar(20) NOT NULL DEFAULT 'recorded'
);
CREATE TABLE cash_session_events (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  session_id uuid NOT NULL REFERENCES cash_sessions(id),
  event_type varchar(40) NOT NULL,
  actor_id uuid NOT NULL REFERENCES iam_users(id),
  reason text,
  event_data jsonb,
  occurred_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE sync_nodes (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  node_type varchar(20) NOT NULL CHECK (node_type IN ('central','store_server','terminal')),
  store_id uuid REFERENCES org_stores(id),
  terminal_id uuid REFERENCES org_terminals(id),
  node_code varchar(60) NOT NULL UNIQUE,
  status varchar(20) NOT NULL DEFAULT 'unknown',
  last_seen_at timestamptz,
  CHECK ((node_type = 'central' AND store_id IS NULL AND terminal_id IS NULL)
      OR (node_type = 'store_server' AND store_id IS NOT NULL AND terminal_id IS NULL)
      OR (node_type = 'terminal' AND store_id IS NOT NULL AND terminal_id IS NOT NULL))
);
CREATE TABLE sync_outbox (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  node_id uuid NOT NULL REFERENCES sync_nodes(id),
  event_id uuid NOT NULL UNIQUE,
  aggregate_type varchar(60) NOT NULL,
  aggregate_id uuid NOT NULL,
  event_type varchar(60) NOT NULL,
  payload jsonb NOT NULL,
  schema_version integer NOT NULL DEFAULT 1,
  status varchar(20) NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','sending','sent','failed')),
  attempts integer NOT NULL DEFAULT 0 CHECK (attempts >= 0),
  next_retry_at timestamptz,
  last_error text,
  occurred_at timestamptz NOT NULL DEFAULT now(),
  sent_at timestamptz
);
CREATE INDEX ix_sync_outbox_due ON sync_outbox(status, next_retry_at, occurred_at);
CREATE TABLE sync_inbox (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  source_node_id uuid NOT NULL REFERENCES sync_nodes(id),
  event_id uuid NOT NULL,
  idempotency_key varchar(140) NOT NULL,
  received_at timestamptz NOT NULL DEFAULT now(),
  processing_status varchar(20) NOT NULL DEFAULT 'received' CHECK (processing_status IN ('received','processed','rejected')),
  response_payload jsonb,
  UNIQUE (source_node_id, event_id),
  UNIQUE (idempotency_key)
);
CREATE TABLE sync_delivery_attempts (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  outbox_id uuid NOT NULL REFERENCES sync_outbox(id),
  attempted_at timestamptz NOT NULL DEFAULT now(),
  result varchar(20) NOT NULL,
  response_code integer,
  error_message text
);
CREATE TABLE sync_checkpoints (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  node_id uuid NOT NULL REFERENCES sync_nodes(id),
  stream_name varchar(60) NOT NULL,
  last_acked_at timestamptz,
  last_event_id uuid,
  UNIQUE (node_id, stream_name)
);
CREATE TABLE sync_master_versions (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  entity_type varchar(60) NOT NULL,
  entity_id uuid NOT NULL,
  version bigint NOT NULL,
  effective_at timestamptz NOT NULL,
  published_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (entity_type, entity_id, version)
);
CREATE TABLE sync_inventory_events (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  source_type varchar(30) NOT NULL,
  source_id uuid NOT NULL,
  event_type varchar(30) NOT NULL,
  payload jsonb NOT NULL,
  idempotency_key varchar(140) NOT NULL UNIQUE,
  status varchar(20) NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','sending','sent','failed')),
  attempts integer NOT NULL DEFAULT 0 CHECK (attempts >= 0),
  next_retry_at timestamptz,
  last_error text,
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (source_type, source_id, event_type)
);
CREATE TABLE md_stock_cache (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  store_id uuid NOT NULL REFERENCES org_stores(id),
  product_id uuid NOT NULL REFERENCES md_products(id),
  quantity integer NOT NULL,
  source_updated_at timestamptz NOT NULL,
  fetched_at timestamptz NOT NULL DEFAULT now(),
  source_version varchar(80),
  UNIQUE (store_id, product_id)
);

CREATE TABLE audit_events (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  store_id uuid REFERENCES org_stores(id),
  terminal_id uuid REFERENCES org_terminals(id),
  actor_id uuid REFERENCES iam_users(id),
  action varchar(100) NOT NULL,
  entity_type varchar(80) NOT NULL,
  entity_id uuid,
  reason text,
  before_data jsonb,
  after_data jsonb,
  occurred_at timestamptz NOT NULL DEFAULT now(),
  correlation_id uuid
);
CREATE INDEX ix_audit_time_actor_store ON audit_events(occurred_at, actor_id, store_id);
CREATE TABLE audit_deletion_events (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  original_audit_event_id uuid NOT NULL,
  deleted_by uuid NOT NULL REFERENCES iam_users(id),
  reason text NOT NULL,
  confirmed_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE ops_store_hours (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  store_id uuid NOT NULL REFERENCES org_stores(id),
  weekday smallint NOT NULL CHECK (weekday BETWEEN 1 AND 7),
  opens_at time NOT NULL,
  closes_at time NOT NULL,
  effective_from date,
  effective_until date,
  is_closed boolean NOT NULL DEFAULT false,
  CHECK (effective_until IS NULL OR effective_from IS NULL OR effective_until >= effective_from)
);
CREATE TABLE ops_store_exceptions (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  store_id uuid NOT NULL REFERENCES org_stores(id),
  starts_at timestamptz NOT NULL,
  ends_at timestamptz NOT NULL,
  reason text NOT NULL,
  created_by uuid NOT NULL REFERENCES iam_users(id),
  CHECK (ends_at > starts_at)
);
CREATE TABLE ops_terminal_printers (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  terminal_id uuid NOT NULL REFERENCES org_terminals(id),
  connection_type varchar(20) NOT NULL CHECK (connection_type IN ('usb','lan','bluetooth')),
  printer_config jsonb NOT NULL DEFAULT '{}'::jsonb,
  is_default boolean NOT NULL DEFAULT false
);
CREATE UNIQUE INDEX uq_default_printer_per_terminal ON ops_terminal_printers(terminal_id) WHERE is_default;
CREATE TABLE ops_print_jobs (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  terminal_id uuid NOT NULL REFERENCES org_terminals(id),
  sale_id uuid NOT NULL REFERENCES pos_sales(id),
  job_type varchar(20) NOT NULL CHECK (job_type IN ('print','reprint')),
  status varchar(20) NOT NULL DEFAULT 'queued',
  created_at timestamptz NOT NULL DEFAULT now(),
  completed_at timestamptz,
  error_message text
);
CREATE TABLE ops_reprint_events (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  sale_id uuid NOT NULL REFERENCES pos_sales(id),
  terminal_id uuid NOT NULL REFERENCES org_terminals(id),
  actor_id uuid NOT NULL REFERENCES iam_users(id),
  reason text NOT NULL,
  printed_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE ops_alerts (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  store_id uuid REFERENCES org_stores(id),
  terminal_id uuid REFERENCES org_terminals(id),
  alert_type varchar(40) NOT NULL,
  severity varchar(20) NOT NULL,
  message text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  acknowledged_by uuid REFERENCES iam_users(id),
  acknowledged_at timestamptz,
  resolved_at timestamptz
);
CREATE TABLE ops_backup_runs (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  node_id uuid NOT NULL REFERENCES sync_nodes(id),
  started_at timestamptz NOT NULL,
  completed_at timestamptz,
  status varchar(20) NOT NULL,
  artifact_uri text,
  size_bytes bigint CHECK (size_bytes IS NULL OR size_bytes >= 0),
  checksum varchar(128)
);

-- Seed the five roles. Permission assignments are intentionally left for a
-- separately reviewed permission matrix; do not grant broad access by default.
INSERT INTO iam_roles(code, name) VALUES
 ('CASHIER','Cashier'),
 ('SUPERVISOR','Store Supervisor'),
 ('STORE_ADMIN','Store Admin'),
 ('CENTRAL_ADMIN','Central Admin'),
 ('OWNER','Owner / Management');

